begin;
\set fixture_include true
\ir helpers/fixtures.sql
\set fixture_include false
select no_plan();

insert into permit_documents (
  source_sha256, original_filename, detected_mime, size_bytes, page_count,
  site_id_candidate, field_candidates, extraction_method, review_storage_path
)
select repeat('1', 64), 'synthetic.pdf', 'application/pdf', 100, 1, id,
  '{"site":{"selected":{"value":"SYNTHETIC","confidence":"high","evidence":"PRIVATE TEXT"},"candidates":[],"conflict_reason":null}}',
  'text', 'private/synthetic.pdf' from sites where code = 'RMC-01';
insert into permit_documents (
  id, source_sha256, original_filename, detected_mime, size_bytes, page_count,
  field_candidates, extraction_method, review_storage_path
) values ('50000000-0000-0000-0000-000000000001', repeat('2', 64), 'unassigned.pdf',
  'application/pdf', 100, 1, '{}', 'text', 'private/unassigned.pdf');

insert into storage.objects(bucket_id, name, metadata) values
  ('permit-documents', 'private/synthetic.pdf', '{"mimetype":"application/pdf","size":100}'),
  ('permit-documents', 'private/unassigned.pdf', '{"mimetype":"application/pdf","size":100}'),
  ('permit-documents', 'private/orphan.pdf', '{"mimetype":"application/pdf","size":100}');

select is((select public from storage.buckets where id = 'permit-documents'), false,
  'review originals remain private');
select ok((select reloptions @> array['security_invoker=true'] from pg_class
  where oid = 'v_admin_permit_document_review'::regclass), 'view preserves invoker RLS');
select ok(not exists (select 1 from information_schema.columns where table_name = 'v_admin_permit_document_review'
  and column_name in ('review_storage_path', 'evidence_storage_path', 'extracted_text', 'review_bucket')),
  'view does not expose storage locations or full OCR text');
select ok(not has_table_privilege('anon', 'v_admin_permit_document_review', 'SELECT'),
  'anonymous callers cannot query review');

set local role authenticated;
select set_config('request.jwt.claim.sub', '00000000-0000-0000-0000-000000000001', true);
select is((select count(*) from v_admin_permit_document_review), 1::bigint,
  'site officer sees only the assigned site draft');
select is((select count(*) from storage.objects where bucket_id = 'permit-documents'), 1::bigint,
  'site officer can read only originals linked to visible drafts');
select set_config('request.jwt.claim.sub', '00000000-0000-0000-0000-000000000004', true);
select is((select count(*) from v_admin_permit_document_review), 2::bigint,
  'active SHE sees assigned and unassigned drafts');
select is((select count(*) from storage.objects where bucket_id = 'permit-documents'), 2::bigint,
  'SHE can review originals but cannot read unrelated orphan uploads');
select ok(not exists(select 1 from v_admin_permit_document_review
  where field_candidates::text like '%PRIVATE TEXT%'), 'view omits candidate evidence text');
select throws_ok($$select confirm_permit_document('50000000-0000-0000-0000-000000000001', '{}')$$,
  'P0001', null, 'confirmation before reviewed candidates are supplied is rejected');
select is((select status::text from permit_documents where id = '50000000-0000-0000-0000-000000000001'),
  'pending_review', 'rejected premature confirmation is atomic');
reset role;

insert into permit_documents (source_sha256, original_filename, detected_mime, size_bytes,
  page_count, extraction_method, review_storage_path, status, error_stage, error_code, error_message)
values (repeat('3', 64), 'corrupt.pdf', 'application/pdf', 100, null, 'none',
  'private/corrupt.pdf', 'failed', 'extraction', 'corrupt_document', 'Safe failure');
select is((select page_count from v_admin_permit_document_review where source_sha256 = repeat('3', 64)),
  null::integer, 'unknown page counts are preserved for failed drafts');
select throws_ok($$insert into permit_documents (source_sha256, original_filename, detected_mime, size_bytes,
  page_count, extraction_method, review_storage_path) values (repeat('4', 64), 'unknown.pdf',
  'application/pdf', 1, null, 'text', 'private/unknown.pdf')$$,
  '23514', null, 'successful extraction still requires a known positive page count');
select * from finish();
rollback;
{
  "name": "era-platform-spec",
  "private": true,
  "scripts": {
    "db:start": "supabase start",
    "db:reset": "supabase db reset",
    "db:test": "supabase test db",
    "db:stop": "supabase stop"
  },
  "devDependencies": {
    "supabase": "^2.119.0"
  }
}

